text:
{
 "quarter": "Q3 FY24",
 "callDate": "2024-02-19",
 "guidance": [
  {
   "metric": "volume",
   "statement": "Coal India targets coal production of 838 million tons for next financial year.",
   "quote": "With that -- keeping that 838 million tons, one target is kept in the 850 million.",
   "page": 4,
   "horizon": "next year",
   "quantitative": true
  },
  {
   "metric": "capex",
   "statement": "CIL targets total capex of INR17,500 crores for the next financial year.",
   "quote": "It is almost INR17,500 crores. This year... It is INR16,500 crores, and INR1,000 crores more, INR17,500 crores.",
   "page": 8,
   "horizon": "FY25",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "The company maintains its target to reach 1 billion tons of production in the future.",
   "quote": "1 billion, we are on course.",
   "page": 5,
   "horizon": "medium term",
   "quantitative": false
  },
  {
   "metric": "other",
   "statement": "Employee cost is expected to decrease by around INR2,000 crores this year and continue downward.",
   "quote": "We are expecting this year, employee cost will be less than the last year to the tune of around INR2,000 crores. And it will continue",
   "page": 12,
   "horizon": "near future",
   "quantitative": true
  },
  {
   "metric": "volume",
   "statement": "E-auction volume is expected to be around 15% in the fourth quarter.",
   "quote": "Around it.",
   "page": 4,
   "horizon": "next quarter",
   "quantitative": true
  },
  {
   "metric": "capex",
   "statement": "Capex is expected to be around INR18,000 crores in FY26.",
   "quote": "In FY '26, it will be around INR18,000 crores.",
   "page": 17,
   "horizon": "FY26",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "volume",
   "statement": "Achieved highest ever 9-month coal production of 531.90 million tons with 11% growth.",
   "page": 3
  },
  {
   "metric": "profit",
   "statement": "Reported highest ever 9-month PBT of INR31,937 crores and PAT of INR23,849 crores.",
   "page": 3
  },
  {
   "metric": "revenue",
   "statement": "Achieved highest ever 9-month revenue from operations of INR1,04,914 crores, up 5%.",
   "page": 3
  },
  {
   "metric": "capex",
   "statement": "CIL achieved a capex of INR5,702 crores in the first 9 months.",
   "page": 3
  },
  {
   "metric": "volume",
   "statement": "Power dispatches reached highest ever 9-month figure of 454.03 million tons.",
   "page": 3
  },
  {
   "metric": "other",
   "statement": "Market capitalization stood at INR2,31,719 crores as of December 31, 2023.",
   "page": 4
  }
 ],
 "tone": "Confident on robust demand and volume growth, with expectations of moderating e-auction premiums.",
 "pushback": [
  {
   "topic": "E-auction premium drop",
   "gist": "Analysts questioned the sharp decline in e-auction premiums compared to previous quarters.",
   "page": 9
  },
  {
   "topic": "Accounting policy change",
   "gist": "Analysts pressed on the impact and tax implications of changing the stripping activity adjustment policy.",
   "page": 7
  },
  {
   "topic": "Volume shortfall",
   "gist": "Analyst asked about the 8 to 9 million ton lag in SECL and whether the overall target will be met.",
   "page": 4
  },
  {
   "topic": "Receivables increase",
   "gist": "Questioned the jump in receivables from INR13,000 crores to INR17,000 crores despite excess inventory.",
   "page": 15
  }
 ]
}
